void os_eligible_insert_head (Tsk tsk)
{
  tsk->tsk_state = OS_TSK_ELIGIBLE ;

  os_pq_insert_head (& os_q_eligible , cast_tsk_to_pq (tsk)) ;
}

/*--------------------------------------------------------------------------*/

void os_eligible_insert_tail (Tsk tsk)
{
  tsk->tsk_state     = OS_TSK_ELIGIBLE      ;
  tsk->tsk_timeslice = tsk->tsk_timeslice_a ;

  os_pq_insert_tail (& os_q_eligible , cast_tsk_to_pq (tsk)) ;
}

